MM.mnemo[24] = {"cards":[{"id":"ko-k3-0417","w":"고르다","cs":"vybrat (si)","en":"to choose","p":"v","o":"k","ex":"뭐 골랐어요?","exc":"Co sis vybral?","h":"KO-RŮ ≈ KORUNA: vybíráš si korunu. 골라요.","m":"Nepravidelné 르: 골라요, 골랐어요. 고르세요 = vyberte si.","tv":["골라요","골랐어요"],"irr":"르"},{"id":"ko-k3-0418","w":"자르다","cs":"krájet; stříhat; řezat; uříznout","en":"to cut","p":"v","o":"k","ex":"누가 케이크 잘랐어요?","exc":"Kdo nakrájel ten dort? (가 → 1. pád)","h":"ČA-RŮ ≈ ČÁRA: krájíš a stříháš podle čáry. 잘라요.","m":"Nepravidelné časování na 르: ㅡ vypadne a zdvojí se ㄹ → 잘라요 (krájí), 잘랐어요 (nakrájel). Používá se na krájení nožem i stříhání nůžkami (머리를 자르다 = ostříhat vlasy).","tv":["잘라요","잘랐어요"],"irr":"르"},{"id":"ko-k3-0419","w":"기르다","cs":"chovat (zvíře); pěstovat (rostliny, vlasy); vychovávat","en":"to grow, to raise","p":"v","o":"k","ex":"토끼를 5년 동안 길렀어요.","exc":"Choval jsem králíka pět let. (를 → 4. pád)","h":"KI-RŮ ≈ KYTKY ROSTOU: pěstuješ kytky, ať rostou. 길러요.","m":"Nepravidelné časování na 르 → 길러요 (chová), 길렀어요 (choval). Říká se nejen o zvířatech a dětech, ale i o vlasech nebo vousech: 머리를 기르다 = nechat si narůst vlasy.","tv":["길러요","길렀어요"],"irr":"르"},{"id":"ko-k3-0420","w":"다르다","cs":"jiný; odlišný; lišit se","en":"to be different","p":"a","o":"k","rz":["다르다 → 달라요 · 달라서 · 달랐어요","být jiný → je jiný · protože je jiný · byl jiný"],"h":"TA-RŮ ≈ TARZAN: Tarzan je jiný než ostatní. 달라요. Příbuzné 다른.","m":"Nepravidelné časování na 르 → 달라요. Pozor na častou záměnu se slovesem 달다 (pověsit; sladký), které má v přítomném čase tvar 달아요. Opak: 같다 (stejný).","tv":["달라요","달랐어요"],"irr":"르"},{"id":"ko-k3-0421","w":"누르다","cs":"zmáčknout, stisknout","en":"to press, to push","p":"v","o":"k","ex":"벨을 누르고 기다리세요.","exc":"Zazvoňte na zvonek a počkejte. (을 → 4. pád; -고 → a)","h":"NU-RŮ ≈ „NO, RŮŽOVÉ!“: zmáčkni to růžové tlačítko. 눌러요.","m":"Nepravidelné 르: 눌러요, 눌렀어요. 벨을 누르다 = zazvonit, 버튼을 누르다 = zmáčknout tlačítko.","tv":["눌러요","눌렀어요"],"irr":"르"},{"id":"ko-k3-0422","w":"마르다","cs":"uschnout; vyschnout; zhubnout; být hubený","en":"to dry (up)","p":"v","o":"k","ex":"머리가 마르기 전에 집을 나왔어요.","exc":"Vyšel jsem z domu dřív, než mi uschly vlasy. (가 → 1. pád; 을 → 4. pád)","h":"MA-RŮ ≈ MARS: na Marsu všechno vyschlo. 말라요.","m":"Nepravidelné časování na 르 → 말라요 (schne), 말랐어요 (uschl / je hubený). Jako přídavné jméno znamená ‚hubený‘ (doslova ‚vyschlý‘): 그 사람은 많이 말랐어요 = Ten člověk je hodně hubený.","tv":["말라요","말랐어요"],"irr":"르"},{"id":"ko-k3-0423","w":"바르다","cs":"natřít, namazat (krém, mast)","en":"to rub, to put on","p":"v","o":"k","rz":["바르다 → 발라요 · 발라서 · 발랐어요","namazat → maže · namaže a · namazal"],"h":"PA-RŮ ≈ PARUKA: namažeš krém pod paruku. 발라요.","m":"Nepravidelné 르: 발라요, 발랐어요. Stejně znějící 바르다 = správný, přímý (바른 자세 = správné držení těla).","tv":["발라요","발랐어요"],"irr":"르"},{"id":"ko-k3-0424","w":"부르다","cs":"zavolat (na někoho); zpívat (píseň)","en":"to call, to address","p":"v","o":"k","ex":"불러도 대답이 없어요.","exc":"I když na něj volám, nikdo neodpovídá. (이 → 1. pád)","h":"PU-RŮ ≈ BURÁCÍ: burácivě na někoho zavoláš nebo zazpíváš. 불러요. Jiné slovo než 배부르다.","m":"Nepravidelné 르: 불러요, 불렀어요. 노래를 부르다 = zpívat. Stejně znějící 배가 부르다 = být sytý.","tv":["불러요","불렀어요"],"irr":"르"},{"id":"ko-k3-0425","w":"서두르다","cs":"pospíchat; spěchat; ukvapit se","en":"to hurry","p":"v","o":"k","ex":"너무 서두르지 마세요.","exc":"Tolik nespěchejte. / Neukvapujte se.","h":"SO-DU-RŮ ≈ „SOUDRUHU, RYCHLE!“: pospíchej! 서둘러요.","m":"Nepravidelné časování na 르 → 서둘러요 (spěchá), 서둘렀어요 (spěchal). Podobný význam má i 급하다 (naléhavý, spěchat).","tv":["서둘러요","서둘렀어요"],"irr":"르"},{"id":"ko-k3-0426","w":"찌르다","cs":"bodnout; píchnout; strčit (prstem)","en":"to stab","p":"v","o":"k","rz":["찌르다 → 찔러요 · 찔러서 · 찔렀어요","bodnout → bodne · protože bodl · bodl"],"h":"ČI-RŮ ≈ CHIRURG: chirurg píchne jehlou. 찔러요.","m":"Nepravidelné časování na 르 → 찔러요, 찔렀어요. Nejde jen o bodnutí nožem, ale i o píchnutí trnem nebo dloubnutí prstem (손가락으로 찌르다).","tv":["찔러요","찔렀어요"],"irr":"르"},{"id":"ko-k3-0427","w":"비행기","cs":"letadlo","en":"airplane","p":"n","o":"s","ex":"비행기는 빨라서 좋아요.","exc":"Letadlo je fajn, protože je rychlé. (는 → téma)","h":"PI-HENG ≈ PÍSKNE HANGÁR: z hangáru se ozve písknutí a vyjede letadlo.","m":"飛 létat + 行 pohybovat se + 機 stroj = létající stroj, tedy letadlo. Vazby: 비행기를 타다 (letět letadlem), 비행기 표 (letenka).","r":["bi-飛","haeng-行","gi-機"]},{"id":"ko-k3-0428","w":"토끼","cs":"králík; zajíc","en":"rabbit","p":"n","o":"k","ex":"토끼를 5년 동안 길렀어요.","exc":"Choval jsem králíka pět let. (를 → 4. pád)","h":"TO-KI ≈ TOČÍ: králík točí ušima.","m":"Čistě korejské slovo se zdvojeným ㄲ (tento zvuk je v češtině ostré, krátké ‚k‘ bez přídechu). Stejný vzor zvířat se zdvojenou souhláskou má i 코끼리 (slon)."},{"id":"ko-k3-0429","w":"동안","cs":"během; po dobu; zatímco","en":"during, for (a period)","p":"n","o":"k","ex":"토끼를 5년 동안 길렀어요.","exc":"Choval jsem králíka pět let. (를 → 4. pád)","h":"TONG-AN ≈ TONGA: během dovolené na ostrově Tonga.","m":"Stojí vždy až za časovým údajem nebo slovesem (nikdy před ním jako v češtině): 5년 동안 (po dobu 5 let), 방학 동안 (během prázdnin)."},{"id":"ko-k3-0430","w":"벨","cs":"zvonek","en":"bell (doorbell)","p":"n","o":"e","ex":"벨을 누르고 기다리세요.","exc":"Zazvoňte na zvonek a počkejte. (을 → 4. pád)","h":"Z angličtiny bell.","m":"Výpůjčka z anglického ‚bell‘ (zvonek). Častá spojení: 벨을 누르다 (zazvonit na zvonek u dveří nebo v autobuse), 벨이 울리다 (zvoní zvonek / vyzvání telefon)."},{"id":"ko-k3-0431","w":"대답","cs":"odpověď","en":"answer, reply","p":"n","o":"s","ex":"불러도 대답이 없어요.","exc":"I když na něj volám, žádná odpověď. / Neozývá se. (이 → 1. pád)","h":"TE-DAP ≈ „TEĎ DEJ“: teď dej odpověď!","m":"對 proti, vůči + 答 odpověď = odpověď (na otázku nebo zavolání). Sloveso: 대답하다 = odpovědět. Stejné 答 je i ve slově 정답 (správná odpověď).","hada":1,"r":["dae-對","dap-答"]}],"gram":{"id":"ko-k3-g24","w":"르 불규칙","en":"Irregulars: 르","cs":"nepravidelná slovesa a přídavná jména na 르","vy":"U většiny sloves a přídavných jmen končících na 르 (např. 고르다, 모르다, 빠르다, 기르다) dochází při spojení s koncovkou začínající na -아/어 (např. -아요/어요, -아서/어서, -았어요/었어요) ke zdvojení souhlásky ㄹ. Samohláska ㅡ vypadne, jedno ㄹ se připojí jako spodní souhláska k předchozí slabice a druhé ㄹ začne slabiku novou (고르다 → 골라요, 기르다 → 길러요). Před koncovkami začínajícími souhláskou (např. -고, -세요, -기) zůstává 르 beze změny.","m":"Při spojení s -아/어 se 르 ‚rozštěpí‘ na dvě ㄹ: jedno spadne dolů do předchozí slabiky a druhé zůstane nahoře (모르다 → 몰라요, 빠르다 → 빨라요). Pozor na vzácné pravidelné výjimky jako 따르다 (následovat → 따라요) a 치르다 (složit zkoušku → 치러요).","s":[["고르다 → 골라요 · 골라서 · 골랐어요","vybrat si → vybírám si · vyberu si a pak / protože si vybírám · vybral jsem si"],["모르다 → 몰라요 · 몰라서 · 몰랐어요","nevědět → nevím · protože nevím · nevěděl jsem"],["기르다 → 길러요 · 길러서 · 길렀어요","chovat, pěstovat → chovám · chovám a pak · choval jsem"],["뭐 골랐어요?","Co sis vybral?"],["저도 몰라요.","Já taky nevím."],["비행기는 빨라서 좋아요.","Letadla jsou dobrá, protože jsou rychlá."],["누가 케이크 잘랐어요?","Kdo nakrájel ten dort?"],["토끼를 5년 동안 길렀어요.","Pět let jsem choval králíka."],["주연 씨, 마시고 싶은 거 골랐어요?","Džujon, už sis vybrala, co bys chtěla pít?"],["아니요, 아직 안 골랐어요.","Ne, ještě jsem si nevybrala."],["빨리 고르세요.","Vyberte si rychle. (před -세요 zůstává 르 beze změny)"],["벨을 누르고 기다리세요.","Zazvoňte na zvonek a počkejte. (před -고 zůstává 르 beze změny)"],["너무 빨라서 못 봤어요.","Bylo to moc rychlé, takže jsem to neviděl."],["불러도 대답이 없어요.","I když na něj volám, neodpovídá."],["머리가 마르기 전에 집을 나왔어요.","Vyšel jsem z domu dřív, než mi uschly vlasy."],["저는 잘 모르는데, 왜요?","Moc o tom nevím, ale proč se ptáš?"],["좋은 차를 고르기 위해서 많은 사람들한테 물어봤어요.","Ptal jsem se mnoha lidí, abych si vybral dobré auto."],["저희 가족은 강아지 두 마리를 기르고 있어요.","Naše rodina chová dva pejsky."],["너무 서두르지 마세요.","Nespěchejte tolik."]]}};
Object.assign(MM.mnRoots, {"bi-飛":["비","飛","létat"],"haeng-行":["행","行","jít, konat"],"gi-機":["기","機","stroj; příležitost"],"dae-對":["대","對","proti, vůči"],"dap-答":["답","答","odpověď"]});
